for id,why in [('TC-A03','Four persistent ODE states correspond directly to author-image rates; author code also evolves stress/viscous/total-strain components. The reduced state identity is explicitly different.'),('TC-A04','Algebraic stress depends on current rate. A stress hold is an inverse control problem, not zero-rate relaxation. Incoming-rate stress capture and left/right transition metadata are necessary.'),('TC-A05','Author BDF and outer-step acceleration terms have a different integration algorithm from the Atlas ODE/control solver. Passing reference comparisons cannot establish algorithm identity;2.5e-9 is a study setting, not an approved default.')]:
 add(id,'terracotta-2024','supported',why,TC,exclude='Full ten-state author BDF/mixed-control numerical equivalence.')
add('TC-P02','terracotta-2024','conditional','Existing v0.3 crosswalk correctly names physical_time/ode,axisymmetric_x,fixed_spatial,Mandel,total observable stress and explicit state/rate/time. Migration can be scoped after source decisions; historical v0.2 evidence must retain its identity.',TC+[('docs/ingestion/terracotta-2024/journal-followup-v1/schema-crosswalk-v03.json','formulation/state/init mapping')],conditions='Resolve TC-P01 choices and bind a new exact definition; inspect state physical meanings and dimensional consistency, preserving historical bytes.',exclude='Automatic inherited old-hash qualification, general3D or finite rotations.',follow='After source decisions, migration owner stages the new candidate under its own identity.')
add('TC-P03','terracotta-2024','conditional','Saved refined study passes each phase/channel on both backends; independently recomputed maximum fraction.586009. Parent full-path accuracy remains failed. This supports reuse of unchanged reference bytes, not a new definition pass.',TC+[('catalogue/investigations/terracotta-preparation-hold-refinement-v2/assessment.json','both backends/errors'),('docs/reviews/production-admission-agent-v1/checks.json','terracotta_saved_component_check')],conditions='Freeze new artifact/compiler/reference/policy; retain own preparation/capture/clock and the23-to22observation mapping; add model-specific rejection/restart cases before public host qualification.',exclude='Current-artifact release evidence, endpoint-only accuracy or silently loosened gates.',follow='Execute the defined changed-artifact matrix only after source/identity decisions; do not repeat old reference generation.')
add('TC-P04','terracotta-2024','conditional','The required clock,state,strain,finite endpoint-rate restart and failed-interval semantics are appropriate. The recorded86,098–92,404substeps per30s path consume86–92%of100,000cap; no evidence establishes browser workload suitability or complete model-specific recovery.',TC,conditions='Freeze real timed host fixtures, workload limits, unsupported axisymmetry cases and state/strain/clock rollback; qualify actual package and explicit numerical settings.',exclude='Approved interactive default or complete-update tangent.',follow='After TC-P03, run the bounded packaged host/restart/workload matrix under new identity.')
add('TC-P05','terracotta-2024','unresolved','Journal identity/inequalities, new definition, host qualification and scientific procedure remain open. Passing numerical refinement does not close these conditions.',TC,exclude='Reviewed production admission and experimental validation.',follow='Keep research label; decide exact scoped admission only after TC-P01–04 outcomes.')
SAN=[('docs/ingestion/sanisand-2004/production-closure-v1/README.md','Decisions; singular branches; ordered acceptance'),('docs/models/sanisand-2004-original.md','continuous equation mapping')]
add('D01','sanisand-2004','supported','A separately named fixed-memory backward-Euler research variant is a coherent bounded target. Original2004 law, OpenSees numerical modifications and canonical reversal have distinct identities. Source original pages623,628,629,631 were independently read.',SAN,exclude='Canonical full cyclic2004 release or complete OpenSees implementation equivalence.')
add('D02','sanisand-2004','supported','Original Eq3 explicitly uses current e. Printed Eq20 numerator lacks K in the volumetric term while its preceding relation n:ds-(n:r)dp and dp=K[dv-LD] require K; dimensions and elimination both support the disclosed correction. Uneliminated stress/plastic residual avoids copying the faulty loading numerator.',SAN+[('docs/models/sanisand-2004-fixed-memory-be.md','Finite product residuals; source correction'),('catalogue/source-audits/sanisand-2004-original-equations.json','typed source equations/correction')],exclude='Verbatim printed Eq20 or an undisclosed source erratum.')
add('D03','sanisand-2004','supported','Explicit sigma,e,alpha,fabric,alpha_in is necessary:25persistent scalar components plus temporary gamma. Isotropic zero histories are a manufactured initial hypothesis, not universal Toyoura specimen preparation. e0 is critical-line intercept, not initial specimen e.',SAN,exclude='Automatic preparation from Table1, density alone or scalar z=0 example.')
add('D04','sanisand-2004','conditional','For d>0, L=dA/(Hbar+dE) and Lh=b0 A/(Hbar+dE) are exact branch algebra. At d→0+,Hbar>0 the latter remains finite while plastic strain vanishes. Independent rational convergence confirms that setting L=0 prematurely loses backstress evolution. These are continuous limits, not a proof of all finite-step roots.',SAN+[('docs/models/sanisand-2004-hardening-limit.md','regular one-sided limit'),('docs/reviews/production-admission-agent-v1/checks.json','sanisand_finite_product_limit')],conditions='Independent full-state plastic reference and precision/branch gates must test regular initiation and reject unsupported simultaneous-zero,Hbar<=0,d<0 and singular loading denominators.',exclude='Universal singular-state continuation or finite-step uniqueness.',follow='Freeze and review finite-path reference before observing new candidate outputs.')
add('D05','sanisand-2004','conditional','Off-cone n normalization, centre fallback, exponential volume and complementarity are disclosed project choices. The exact elastic locator rejects a whole predictor leaving domain even if yield may occur earlier, so it cannot silently serve as a production event integrator.',SAN+[('docs/models/sanisand-2004-elastic-entry.md','audit domain and complete predictor restriction')],conditions='Freeze exact domain/tolerance/branch rejection and transaction policy; retain gamma=Delta_lambda*h semantics rather than calling it accumulated plastic strain.',exclude='Source-prescribed finite-step algorithm or universal yield/domain event order.',follow='Resolve D08 reference/event conventions; use existing implicit update initially and measure entry refinement.')
add('D06','sanisand-2004','conditional','Monotonic fixed memory is suitable for a bounded research milestone, not immediately production-ready. Fresh first-yield identities match18signed entries on the3x3density/pressure grid; no full independent plastic trajectory is present.',SAN+[('docs/reviews/production-admission-agent-v1/checks.json','sanisand_first_yield; extension uses negative magnitude')],conditions='Resolve D04/D05/D08, construct oracle then stage a new v0.3 candidate. Enforce/publish the monotonic-use restriction and bind new evidence.',exclude='Correct reversals from successful calls or original-model scientific admission.',follow='REF-sanisand-monotonic-v1 is the next execution-free reference task after agreed scope.')
add('D07','sanisand-2004','unresolved','Original p631 explicitly delegates negative-distance loading-process updates to Dafalias1986 and distinguishes conjugate-point distances. Exact1986 rules unavailable. Parent Ce*de guard and cone-normal criterion need not have the same sign; more success counts cannot establish equivalence.',SAN+[('catalogue/source-audits/sanisand-1986-loading-process.json','missing primary source and conditional mapping identity')],exclude='Canonical reversal, nested/process mapping or partition invariance of parent-reset variant.',follow='Obtain exact1986 readable source or choose a separately reviewed parent-reset project variant with partition dependence disclosed.')
add('D08','sanisand-2004','conditional','The eight reference families identify useful gaps and deliberately leave numeric budgets unfrozen. This is honest readiness planning; source-review acceptance, precision adequacy and per-channel/event/derivative budgets are still missing, so backend observation is premature.',SAN+[('docs/ingestion/sanisand-2004/production-closure-v1/reference-plan.json','must_freeze_before_candidate; familiesE01–B01')],conditions='Complete the stated prospective decimal/binary controls, sample grid, oracle precision, accuracy/control/event/rollback budgets and corruption review before candidate runs.',exclude='Frozen production policy, independent full-state trajectory pass or release readiness.',follow='Turn reference-plan into a separately named reviewed freeze without candidate observations.')
assert len(D)==41
